// Concrete WebSocket handler with behavior controlled via per-object attributes.
class FuzzWSHandler : public CivetWebSocketHandler {
public:
    // All behaviors are determined at call time by reading attributes stored on this object.
    // This avoids capturing FUZZ_PARAM values in constructors (which broke earlier builds).
    bool handleConnection(CivetServer * /*server*/, const struct mg_connection * /*conn*/) override {
        // Default to true if attribute not set (keep socket open paths exercised).
        int v = FUZZ_GET_ATTR_INT(this, "accept_on_connect");
        return v != 0;
    }
    void handleReadyState(CivetServer * /*server*/, struct mg_connection * /*conn*/) override {
        // No I/O; intentionally a no-op for fuzzer speed.
    }
    bool handleData(CivetServer * /*server*/, struct mg_connection * /*conn*/, int /*bits*/, char * /*data*/, size_t /*data_len*/) override {
        // Default to true to keep the connection open unless attribute says otherwise.
        int v = FUZZ_GET_ATTR_INT(this, "keep_open_on_data");
        return v != 0;
    }
    void handleClose(CivetServer * /*server*/, const struct mg_connection * /*conn*/) override {
        // No-op
    }
};

