import random
import string
from typing import List

# This generator produces URL-encoded strings designed to exercise CivetServer::urlDecode
# across its overloads and the is_form_url_encoded flag. We keep inputs valid and varied.

# Character classes per RFC3986
_UNRESERVED = string.ascii_letters + string.digits + "-._~"
_SUB_DELIMS = "!$&'()*+,;="
_GEN_DELIMS = ":/?#[]@"
_HEX = "0123456789ABCDEF"

def _pct_encode_byte(b: int) -> str:
    return "%" + _HEX[(b >> 4) & 0xF] + _HEX[b & 0xF]

def _random_utf8_bytes(rng: random.Random, max_len: int) -> bytes:
    # Generate valid UTF-8 byte sequences (though URL encoding treats bytes, this adds variety)
    # Mix ASCII, 2-byte, 3-byte, and 4-byte code points.
    out = bytearray()
    target = rng.randint(1, max_len)
    while len(out) < target:
        t = rng.random()
        if t < 0.55:
            out.append(rng.choice(list(b"\x20" + bytes(_UNRESERVED, 'ascii'))))
        elif t < 0.75:
            cp = rng.randint(0x80, 0x7FF)
            out.extend(chr(cp).encode('utf-8'))
        elif t < 0.95:
            cp = rng.randint(0x800, 0xFFFF)
            # Avoid surrogates
            if 0xD800 <= cp <= 0xDFFF:
                cp = 0xE000
            out.extend(chr(cp).encode('utf-8'))
        else:
            cp = rng.randint(0x10000, 0x10FFFF)
            out.extend(chr(cp).encode('utf-8'))
        if len(out) > max_len:
            break
    return bytes(out[:max_len])

def _encode_form_style(rng: random.Random, raw: bytes, allow_plus: bool) -> str:
    # Encode bytes into application/x-www-form-urlencoded-like string.
    # Space may be encoded as '+' if allow_plus, else as %20; other bytes may be percent-encoded or left as-is for unreserved.
    out: List[str] = []
    for b in raw:
        ch = chr(b)
        if ch in _UNRESERVED:
            out.append(ch)
        elif ch == ' ' and allow_plus:
            out.append('+')
        elif ch in _SUB_DELIMS or ch in _GEN_DELIMS:
            # Occasionally keep delimiters literal to test decoding vs percent-encoded
            if rng.random() < 0.4:
                out.append(ch)
            else:
                out.append(_pct_encode_byte(b))
        else:
            out.append(_pct_encode_byte(b))
    # Randomly insert percent-encoded sequences for unreserved to form duplicates/edge cases
    if len(out) > 0 and rng.random() < 0.6:
        idxs = list(range(len(out)))
        rng.shuffle(idxs)
        for i in idxs[: max(1, len(out)//10)]:
            s = out[i]
            if len(s) == 1 and s in _UNRESERVED:
                out[i] = _pct_encode_byte(ord(s))
    return ''.join(out)

def _add_query_params(rng: random.Random, base: str) -> str:
    # Build a query string with repeated keys, encoded values, and mixed separators.
    params = []
    # Always include keys that will be searched by typical fuzzers (e.g., name, id)
    keys = [
        'name', 'id', 'q', 'token', 'session', 'param', 'empty', 'space', 'utf8',
        'plus', 'percent', 'long', 'repeat', 'multi', 'flag'
    ]
    rng.shuffle(keys)
    n = rng.randint(5, 10)
    for i in range(n):
        k = keys[i % len(keys)]
        # Value patterns
        choice = rng.randint(0, 8)
        if k == 'empty' or choice == 0:
            v_raw = b''
        elif k == 'space' or choice == 1:
            v_raw = b' ' * rng.randint(1, 5)
        elif k == 'utf8' or choice == 2:
            v_raw = _random_utf8_bytes(rng, rng.randint(2, 24))
        elif k == 'plus' or choice == 3:
            v_raw = b'one+two + three'
        elif k == 'percent' or choice == 4:
            v_raw = b'%value%with%percents%'
        elif k == 'flag' or choice == 5:
            v_raw = b'1'
        elif k == 'long' or choice == 6:
            v_raw = _random_utf8_bytes(rng, rng.randint(24, 80))
        elif k == 'repeat' or choice == 7:
            v_raw = b'value'
        else:
            v_raw = (k * rng.randint(1, 4)).encode('utf-8')
        allow_plus = rng.random() < 0.5
        v_enc = _encode_form_style(rng, v_raw, allow_plus)
        # Sometimes omit value to produce key-only parameter
        if rng.random() < 0.15:
            params.append(k)
        else:
            params.append(f"{k}={v_enc}")
    # Add repeated keys explicitly
    rep_key = rng.choice(['repeat', 'q', 'name'])
    for occ in range(rng.randint(2, 4)):
        params.append(f"{rep_key}=" + _encode_form_style(rng, b'rep' + bytes([48+occ]), True))
    sep = '&' if rng.random() < 0.7 else ';'
    query = sep.join(params)
    if base:
        # Append as path? or as full URL query
        if '?' in base:
            return base + (sep if not base.endswith('?') else '') + query
        else:
            return base + '?' + query
    return query

def _build_full_urlencoded(rng: random.Random) -> str:
    # Build a realistic URL-encoded string: could be a full URL, a path with query, or just a query/body
    mode = rng.randint(0, 4)
    if mode == 0:
        # Just a query
        return _add_query_params(rng, '')
    elif mode == 1:
        # Path + query
        path_parts = []
        depth = rng.randint(1, 4)
        for _ in range(depth):
            raw = _random_utf8_bytes(rng, rng.randint(3, 10))
            # Encourage %2F and reserved chars inside segment
            seg = _encode_form_style(rng, raw, allow_plus=False).replace('/', '%2F')
            path_parts.append(seg)
        path = '/' + '/'.join(path_parts)
        return _add_query_params(rng, path)
    elif mode == 2:
        # Full URL
        scheme = rng.choice(['http', 'https'])
        host = ''.join(rng.choice(string.ascii_lowercase + string.digits) for _ in range(rng.randint(3, 8)))
        tld = rng.choice(['com','org','net','io'])
        base = f"{scheme}://{host}.{tld}/"
        return _add_query_params(rng, base)
    elif mode == 3:
        # Form body style without key-value structure
        raw = _random_utf8_bytes(rng, rng.randint(10, 60))
        return _encode_form_style(rng, raw, allow_plus=True)
    else:
        # Mixed: pre-encoded reserved literals and percent sequences
        pieces = []
        for _ in range(rng.randint(5, 12)):
            choice = rng.random()
            if choice < 0.4:
                b = rng.choice(list(bytes(_UNRESERVED, 'ascii')))
                pieces.append(chr(b))
            elif choice < 0.7:
                b = rng.randrange(0, 256)
                pieces.append(_pct_encode_byte(b))
            else:
                pieces.append(rng.choice(list(_SUB_DELIMS + _GEN_DELIMS)))
        return ''.join(pieces)

def _cap_length(s: str, max_len: int = 256) -> str:
    # Ensure within fuzzer stub limit (it truncates to 256). Keep our limit too.
    if len(s) <= max_len:
        return s
    return s[:max_len]

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Create several candidate encodings and pick one to diversify per seed
    candidates = []
    # Candidate emphasizing '+' spaces
    raw1 = b"hello world with spaces and+pluses"
    candidates.append(_encode_form_style(rng, raw1, allow_plus=True))
    # Candidate emphasizing %HH sequences including unreserved
    raw2 = _random_utf8_bytes(rng, 48)
    candidates.append(_encode_form_style(rng, raw2, allow_plus=False))
    # Query string with repeated keys
    candidates.append(_build_full_urlencoded(rng))
    # Mixed reserved characters
    mixed = ''.join(rng.choice(list(_UNRESERVED + _SUB_DELIMS + _GEN_DELIMS)) for _ in range(rng.randint(20, 60)))
    candidates.append(mixed)
    # Raw percent-heavy string
    pct_heavy = '&'.join([_pct_encode_byte(rng.randrange(0,256)) for _ in range(rng.randint(15, 40))])
    candidates.append(pct_heavy)

    s = rng.choice(candidates)
    s = _cap_length(s, 256)
    # Return as bytes; fuzzer stub will treat as std::string and may add a NUL for the C-string overload
    return s.encode('utf-8', errors='strict')
